            double energy;
            double h;

            // Calcular la energía del fotón
            energy = (6.62607004 * Math.Pow(10, -34) * speedOfLight) / lengthLength;

            // Calcular la constante de Planck desde la energía y la velocidad de la luz
            h = energy / speedOfLight;

