   import org.springframework.http.HttpHeaders
   import org.springframework.http.HttpStatus
   import org.springframework.http.MediaType

   import com.fasterxml.jackson.databind.ObjectMapper
   import gauges.Inform
   import org.assertj.core.api.Assertions.assertThat

   @StepDefinitions
   class InvoiceManagementSteps {

     OracleSteps.oracleSteps oracleSteps

     @Before
     def setup() {
       oracleSteps.setup()
     }

     @After
     def cleanup() {
       oracleSteps.cleanup()
     }

     Inform inform

     def given() {
       // Define Given steps using OracleSteps and DataFaker
       // Example: Given I have a valid invoice payload
     }

     def when() {
       // Define When steps for making HTTP requests using Spring Boot Test
       // Example: When I POST the invoice payload to the "/invoices" endpoint
       inform.title("Sending POST request to create invoice...")
       def response = oracleSteps.postInvoice(invoice, headers)

       // Set response status code and body
       def statusCode = response.statusCode
       def responseBody = new String(response.body)

       // Inform result
       inform.description("Response status code: $statusCode")
       inform.description("Response body: $responseBody")
     }

     def then() {
       // Define Then steps using AssertJ and OracleSteps
       // Example: Then The response status code is 201
       // Example: And The invoice is created in Oracle EBS

       when {
         Inform inform ->

           // Check response status code and body
           def expectedStatusCode = HttpStatus.CREATED.value()
           assertThat(inform.descriptions[0]).isEqualTo("Response status code: $expectedStatusCode")

           def invoiceId = extractInvoiceId(responseBody)
           oracleSteps.waitForInvoiceToExist(invoiceId)

           // Get the created invoice from the database and assert its values
           def actualInvoice = oracleSteps.getJpaEntityById(Invoice, invoiceId)
           def expectedInvoice = given().invoice

           assertThat(actualInvoice.id).isEqualTo(expectedInvoice.id)
           assertThat(actualInvoice.customerName).isEqualTo(expectedInvoice.customerName)
           assertThat(actualInvoice.invoiceNumber).isEqualTo(expectedInvoice.invoiceNumber)
           assertThat(actualInvoice.invoiceDate).isEqualTo(expectedInvoice.invoiceDate)

           inform.passed()
       }
       .where({
         def expectedStatusCode -> it.statusCode == expectedStatusCode
       })

       when:
       // Define Then steps for handling errors
       // Example: Then The response status code is 400
       // Example: And The response body contains the error messages

       inform.title("Checking response status code and body...")
       def actualStatusCode = response.statusCode
       def actualResponseBody = new String(response.body)

       switch (actualStatusCode) {
         case HttpStatus.BAD_REQUEST.value():
           inform.description("Expected status code: 400")
           def expectedErrorMessage = "Invalid invoice payload"
           assertThat(actualResponseBody.contains(expectedErrorMessage)).isTrue()
           inform.passed()
           break
         case HttpStatus.INTERNAL_SERVER_ERROR.value():
           inform.description("Expected status code: 500")
           def databaseErrorMessage = "Error connecting to Oracle EBS database"
           assertThat(actualResponseBody.contains(databaseErrorMessage)).isTrue()
           inform.passed()
           break
         case HttpStatus.UNAUTHORIZED.value():
           inform.description("Expected status code: 401")
           def unauthorizedErrorMessage = "Access token is invalid or missing"
           assertThat(actualResponseBody.contains(unauthorizedErrorMessage)).isTrue()
           inform.passed()
           break
         default:
           inform.failed()
       }

     }

     private String extractInvoiceId(String responseBody) {
       return objectMapper.readValue(responseBody, Map).get("invoiceId").toString()
     }

     private HttpHeaders getHeaders() {
       def headers = new HttpHeaders()
       headers.setContentType(MediaType.APPLICATION_JSON)
       return headers
     }

     private def postInvoice(Map invoice, HttpHeaders headers) {
       def url = "http://localhost:8080/invoices"
       def json = objectMapper.writeValueAsString(invoice)
       def requestEntity = new HttpEntity<>(json, headers)

       def response = restTemplate.postForEntity(url, requestEntity, String)

       return response
     }
   }
