3. Add the following JavaScript code to load the `.glb` file and its animations:

   ```
   const glTFLoader = new THREE.GLTFLoader();
   glTFLoader.load('your-glb-file.glb', (gltf) => {
     const root = gltf.scene;
     root.traverse((child) => {
       if (child.isMesh) {
         child.castShadow = true;
         child.receiveShadow = true;
       }
     });
     glTF.scene.traverse((child) => {
       if (child.isAnimationAction) {
         const animations = child.animations;
         for (let I = 0; I < animations.length; i++) {
           const animation = animations[i];
           const animationClip = animation.clip;
           const animationTrack = animation.tracks[0];
           const mixer = new THREE.AnimationMixer(child);
           const action = mixer.clipAction(animationClip);
           action.setLoop(THREE.LoopRepeat, -1);
           action.play();
           animationTrack.add(mixer);
         }
       }
     });
     const scene = new THREE.Scene();
     scene.add(gltf.scene);
     const renderer = new THREE.WebGLRenderer();
     renderer.setSize(window.innerWidth, window.innerHeight);
     document.body.appendChild(renderer.domElement);
     function animate() {
       requestAnimationFrame(animate);
       glTF.mixer.update(0.033);
       renderer.render(scene, glTF.camera);
     }
     animate();
   });
   ```

   This code loads the `.glb` file using the `glTFLoader` library, creates and sets up the animation mixer and plays the animations for each mesh that has an animation track. You'll also need to create a camera, a scene, and a renderer to display the `.glb` object and its animations.

