from OpenGL.GL import gltf

# Load shaders for GLSL 3.3 (the minimum version required for glTF 2.0)
vertex_shader_source = """
#version 330
uniform mat4 projection;
uniform mat4 modelview;
uniform mat4 transform;

in layout(location = 0) vec4 position;

void main()
{
    gl_Position = transform * modelview * projection * position;
}
"""

fragment_shader_source = """
#version 330
out vec4 out_color;

void main()
{
    out_color = vec4(1.0, 1.0, 1.0, 1.0);
}
"""

# Load glTF scene and retrieve the first mesh
