gltf_scene.parse_gltf_strings(gltf_buffer)

meshes = gltf_scene.get_scene().nodes[0].children
mesh = meshes[0]

# Compile vertex and fragment shaders
shader_program = shaders.compileProgram(
    shaders.compileShader(vertex_shader_source, gl.GL_VERTEX_SHADER),
    shaders.compileShader(fragment_shader_source, gl.GL_FRAGMENT_SHADER)
)

# Enable depth testing and depth write
gl.glEnable(gl.GL_DEPTH_TEST)
gl.glDepthMask(True)

# Create VAO and VBO for the mesh
vao = gl.glGenVertexArrays(1)
gl.glBindVertexArray(vao)
vbo = gl.glGenBuffers(1)
gl.glBindBuffer(gl.GL_ARRAY_BUFFER, vbo)

# Get the positions buffer and bind it to GL_ARRAY_BUFFER
attribute_buffer_view = mesh_prefix_buffers[mesh][0]
attribute_buffer_id = attribute_buffer_view.buffer_view.resource_id
gl.glBufferData(gl.GL_ARRAY_BUFFER, attribute_buffer_view.buffer_view.byte_length, None, gl.GL_DYNAMIC_DRAW)
gl.glBufferSubData(gl.GL_ARRAY_BUFFER, attribute_buffer_view.offset, attribute_buffer_view.byte_length, attribute_buffer_view.data)

# Set position attribute pointer
stride = attribute_buffer_view.bytes_per_attribute * attribute_buffer_view.component_type.size
offset = attribute_buffer_view.byte_offset // attribute_buffer_view.bytes_per_attribute

gl.glVertexAttribPointer(
    0,  # Attribute index
    attribute_buffer_view.component_type.size,  # Component count
    attribute_buffer_view.component_type,  # Numeric type
    False,  # normalized
    stride,  # Stride (bytes)
    offset  # Offset (bytes)
)
gl.glEnableVertexAttribArray(0)

# Load textures
texture_ids = [texture.bindTexture(gl.GL_TEXTURE_2D) for texture in mesh.textures]

# Draw the mesh
gl.glDrawArrays(gl.GL_TRIANGLES, 0, mesh.attribute_arrays[0].count // mesh.primitives[0].attribute_format.component_count)

# Clean up
gl.glDeleteVertexArrays(1, [vao])
gl.glDeleteBuffers(1, [vbo])
for texture_id in texture_ids:
    gl.glDeleteTextures(1, [texture_id])
