import scala.io.Source

case class Entrepreneur(
  ageRange: Option[Int],
  gender: String,
  educationLevel: String,
  startupIndustry: String,
  funding: Option[Double]
)

object EntrepreneursDataAnalysis {

  // Define functions for data transformation
  def parseEntrepreneur(line: String): Option[Entrepreneur] = {
    val fields = line.split(",").map(_.trim)
    if (fields.length == 5) {
      Some(Entrepreneur(
        ageRange = Option(fields(0).toInt),
        gender = fields(1),
        educationLevel = fields(2),
        startupIndustry = fields(3),
        funding = Option(fields(4).toDouble)
      ))
    } else {
      None
    }
  }

  def extractCharacteristics(data: List[Entrepreneur]): Map[String, List[Any]] = {
    data.filter(_.ageRange.isDefined).groupMapReduce(_.educationLevel)(_.ageRange.toList, _ ++ _)
      .map {
        case (educationLevel, ages) =>
          (educationLevel, (ages.groupMap { age => age / 10 }.mapValues(_.size).toList.sortBy(_._1), ages.size))
      }
      .sortBy { case (_, (ages, count)) => -ages.headOption.getOrElse((0, 0))._2 }
      .take(5)
      .toMap
  }

  def analyzeEntrepreneurs(filePath: String): Map[String, List[(Int, Int)]] = {
    val data = Source.fromFile(filePath).getLines().toList.flatMap(parseEntrepreneur)

    // Impute missing funding values with the median
    val imputedData = data.filter(_.funding.isDefined).reverse
      .foldRight(imputedData.reverse) {
        case (next, result) =>
          val median = result.filter(_.funding.isDefined).map(_.funding.get).sorted match {
            case x if x.isEmpty => 0.0
            case x if x.length % 2 == 1 => x(x.length / 2)
            case x => (x(x.length / 2 - 1) + x(x.length / 2)) / 2.0
          }

          val imputed = if (next.funding.isEmpty) next.copy(funding = Some(median)) else next
          imputed :: result
      }

    // Extract important characteristics while preserving the dataset's diversification
    val characteristics = extractCharacteristics(imputedData)

    // Calculate the distribution of ages within each education level, aggregating for each subset
    characteristics
      .map {
        case (educationLevel, (agesAndCounts, totalCount)) =>
          val ageCounts = agesAndCounts.map {
            case (ageRange, count) =>
              val minAge = math.min(ageRange._1, 10 * (ageRange._1 / 10 + 1))
              val maxAge = math.min(ageRange._2, 10 * (ageRange._2 / 10 + 1))
              (minAge, maxAge, count)
          }

          (educationLevel, (ageCounts, totalCount))
      }
      .filter { case (_, (_, totalCount)) => totalCount >= 1000 } // Filter outliers
      .toMap
  }

