import 'node-sass';
import 'reflect-metadata';

import { createServer } from 'http';
import { Server } from 'socket.io';
import { apply, createMiddleware } from 'spoke';

import { Container } from 'typeorm/connectionoptions';
import { ConnectionOptions } from 'typeorm';

import { AppDataSource } from './data-source';
import { Startup } from './startup';
import { env } from './env';
import express from 'express';

async function start() {
  const app = express();
  const httpServer = createServer(app);

  const container = new Container({});
  container.register<ConnectionOptions>('typeorm.connectionOptions', {
    type: 'postgres',
    host: env.DB_HOST,
    port: env.DB_PORT,
    username: env.DB_USERNAME,
    password: env.DB_PASSWORD,
    database: env.DB_DATABASE,
    entities: [Startup],
    synchronize: true,
  });
  const dataSource = await AppDataSource.initialize();
  container.register('typeorm.dataSource', { provide: 'AppDataSource', useFactory: () => dataSource });

  const middleware = createMiddleware({ container });

  app.use(middleware);

  const io = new Server(httpServer);

  const startup = new Startup(container);
  await startup.run();

  io.on('connection', (socket) => {
    console.log(`User connected: ${socket.id}`);
  });

  httpServer.listen(env.PORT, () => {
    console.log(`Server running on port ${env.PORT}`);
  });
}

start();
```

