class Stack {
    Node top;
    int size;

    Stack() {
        this.top = null;
        this.size = 0;
    }

    void push(int x) {
        Node newNode = new Node(x);

        if (top == null) {
            top = newNode;
        } else {
            newNode.next = top;
            newNode.prev = top.prev;
            top.prev = newNode;

            if (newNode.prev == null) {
                newNode.sum = x + 1;
            } else {
                newNode.sum = newNode.prev.sum + x + 1;
            }
        }

        size++;
    }

    int pop() {
        if (top == null) {
            throw new InvalidOperationException("Stack is empty");
        }

        int value = top.val;
        top = top.next;

        if (top != null) {
            top.prev = null;
        }

        size--;

        return value;
    }

    int seeSaw() {
        if (top == null) {
            throw new InvalidOperationException("Stack is empty");
        }

        int sum = top.next.sum;
        for (Node next = top.next.next; next != null; next = next.next) {
            sum += next.val + 1;
        }

        return sum / (size - 1);
