  'vue/custom-lifecycle-hooks': {
    meta: {
      type: 'problem',
      messages: {
        unexpectedStateModifier: 'Lifecycle hook methods should not modify internal component state directly.',
        callToStateModifier:
          "'{{methodName}}' calls another method that directly modifies internal component state. Please refactor.",
      },
      docs: {
        description: `Detects lifecycle hook methods that modify internal component state and methods that call other methods that modify internal component state. 
          This rule enforces better separation of concerns between event handling, data management, and template rendering in Vue.js components.`,
      },
    },
    create: function (context) {
      const stateModifiers = [
        'patchState',
        'setData',
        'setDataProperty',
        'unsetData',
        'unsetDataProperty',
        // Add more state modifiers as needed
      ];

      function isStateModifier(node) {
        return stateModifiers.some((modifier) =>
          node.callee.object.name === 'this' && node.callee.property.name === modifier
        );
      }

      function detectStateModifiers(path) {
        const { node } {
          if (
            node.type !== 'MethodDefinition' ||
            node.key.type !== 'Identifier' ||
            node.key.name === 'created' ||
            node.key.name === 'destroyed'
          ) {
            return;
          }

          const hasStateModifier = path.find(nodePath => isStateModifier(nodePath));
          const callsAnotherStateModifier = path.some(callPath => {
            const callee = callPath.get('callee');
            return callee.isMemberExpression() &&
              callee.get('object').isThis() &&
              isStateModifier(callee.get('property'));
          });

          if (hasStateModifier) {
            context.report({
              node,
              message: context.options[0] ? context.options[0].unexpectedStateModifier : 'Unexpected state modifier',
            });
          }

          if (callsAnotherStateModifier) {
            const methodName = callPath.get('callee.property').node.name;
            context.report({
              node,
              message: context.options[0]
                ? context.options[0].callToStateModifier.replace('{{methodName}}', methodName)
                : "Method calls another method that modifies internal component state",
            });
          }
        }
      }

      return {
        'MethodDefinition[key.name]': {
          enter(path) {
            detectStateModifiers(path);
          },
        },
      };
    },
  },
};
